const state={lang:'kk',features:[],selected:'398',compare:'304',lat:48,lon:68,rotation:[-68,-34,0],globeZoom:1,mapZoom:1,pan:[0,0],ready:false,projection:'mercator',cache:new Map(),tests:null};
const requestedPoint=(()=>{try{const q=new URLSearchParams(location.search);if(!q.has('lat')||!q.has('lon'))return null;const lat=Number(q.get('lat')),lon=Number(q.get('lon'));M.local(lat,lon);return [lon,lat];}catch(_){return null;}})();
try{state.lang=localStorage.getItem('mercator-language')==='ru'?'ru':'kk';}catch(_){}
const tr=(kk,ru)=>state.lang==='kk'?kk:ru,fmt=(n,d=2)=>Number.isFinite(n)?new Intl.NumberFormat(state.lang==='kk'?'kk-KZ':'ru-RU',{maximumFractionDigits:d,minimumFractionDigits:0}).format(n):'—';
const isoPairs='004 AF,008 AL,010 AQ,012 DZ,024 AO,032 AR,036 AU,040 AT,044 BS,050 BD,051 AM,056 BE,064 BT,068 BO,070 BA,072 BW,076 BR,084 BZ,090 SB,096 BN,100 BG,104 MM,108 BI,112 BY,116 KH,120 CM,124 CA,140 CF,144 LK,148 TD,152 CL,156 CN,158 TW,170 CO,178 CG,180 CD,188 CR,191 HR,192 CU,196 CY,203 CZ,204 BJ,208 DK,214 DO,218 EC,222 SV,226 GQ,231 ET,232 ER,233 EE,238 FK,242 FJ,246 FI,250 FR,260 TF,262 DJ,266 GA,268 GE,270 GM,275 PS,276 DE,288 GH,300 GR,304 GL,320 GT,324 GN,328 GY,332 HT,340 HN,348 HU,352 IS,356 IN,360 ID,364 IR,368 IQ,372 IE,376 IL,380 IT,384 CI,388 JM,392 JP,398 KZ,400 JO,404 KE,408 KP,410 KR,414 KW,417 KG,418 LA,422 LB,426 LS,428 LV,430 LR,434 LY,440 LT,442 LU,450 MG,454 MW,458 MY,466 ML,478 MR,484 MX,496 MN,498 MD,499 ME,504 MA,508 MZ,512 OM,516 NA,524 NP,528 NL,540 NC,548 VU,554 NZ,558 NI,562 NE,566 NG,578 NO,586 PK,591 PA,598 PG,600 PY,604 PE,608 PH,616 PL,620 PT,624 GW,626 TL,630 PR,634 QA,642 RO,643 RU,646 RW,682 SA,686 SN,688 RS,694 SL,702 SG,703 SK,704 VN,705 SI,706 SO,710 ZA,716 ZW,724 ES,728 SS,729 SD,732 EH,740 SR,748 SZ,752 SE,756 CH,760 SY,762 TJ,764 TH,768 TG,780 TT,784 AE,788 TN,792 TR,795 TM,800 UG,804 UA,807 MK,818 EG,826 GB,834 TZ,840 US,854 BF,858 UY,860 UZ,862 VE,887 YE,894 ZM';
const ISO=Object.fromEntries(isoPairs.split(',').map(s=>s.trim().split(' ')));
function name(f){if(!f)return '—';if(f.id==='AFR')return tr('Африка','Африка');const iso=ISO[f.id];if(iso)try{return new Intl.DisplayNames([state.lang],{type:'region'}).of(iso)}catch(_){}return f.properties.name;}
const feature=id=>state.features.find(f=>f.id===id);
function row(a,b,large=false){return `<div class="result-row ${large?'large':''}"><span>${a}</span><b>${b}</b></div>`;}
function setLanguage(){document.documentElement.lang=state.lang;for(const e of document.querySelectorAll('[data-i]'))e.textContent=(state.lang==='kk'?KK:RU)[e.dataset.i]||KK[e.dataset.i];$('lang').innerHTML=state.lang==='kk'?'ҚАЗ <span>/ РУС</span>':'РУС <span>/ ҚАЗ</span>';
 const c=LAB_CONTENT[state.lang];if($('methodContent'))$('methodContent').innerHTML=c.method;
 if($('mapTitle'))$('mapTitle').textContent=state.projection==='mercator'?tr('Меркатор проекциясы','Проекция Меркатора'):'Equal Earth';
 try{localStorage.setItem('mercator-language',state.lang);}catch(_){}
 document.dispatchEvent(new CustomEvent('mercator-language',{detail:state.lang}));
 if(state.ready){populateSelects();renderCountry();drawAll();renderLoadReady();}else if(state.loadError)renderLoadError();renderPoint();renderExperiment();renderPhysical();renderMorph();
}
function populateSelects(){if(!$('country'))return;const opts=state.features.slice().sort((a,b)=>name(a).localeCompare(name(b),state.lang)).map(f=>`<option value="${esc(f.id)}">${esc(name(f))}</option>`).join('');$('country').innerHTML=opts;$('compareCountry').innerHTML=opts;$('country').value=state.selected;$('compareCountry').value=state.compare;$('country').disabled=false;$('compareCountry').disabled=false;
 $('presets').innerHTML=['398','304','AFR','124','643','076','036'].map(id=>`<button data-country="${id}" class="${state.selected===id?'selected':''}">${esc(name(feature(id)))}</button>`).join('');for(const b of $('presets').children)b.onclick=()=>selectCountry(b.dataset.country);}
function metrics(f){if(state.cache.has(f.id))return state.cache.get(f.id);const d=d3.geoBounds(f),A=d3.geoArea(f)*M.R*M.R,center=d3.geoCentroid(f);let Am=null,AmCoarse=null;
 if(d[0][1]>-89&&d[1][1]<89){const p=d3.geoMercator().scale(1).translate([0,0]).clipExtent([[-Math.PI-1e-8,-20],[Math.PI+1e-8,20]]);AmCoarse=d3.geoPath(p.precision(1e-5)).area(f)*M.R*M.R;Am=d3.geoPath(p.precision(2.5e-6)).area(f)*M.R*M.R;}
 const val={A,Am,K:Am===null?null:Am/A,bounds:d,center,numericChange:Am?Math.abs(Am-AmCoarse)/Am*100:null};state.cache.set(f.id,val);return val;}
function selectCountry(id,clickPoint){const f=feature(id);if(!f)return;state.selected=id;const m=metrics(f);const c=m.center.every(Number.isFinite)?m.center:[0,0];state.rotation=[-c[0],-Math.max(-75,Math.min(75,c[1])),0];state.globeZoom=1;state.mapZoom=1;state.pan=[0,0];const p=clickPoint||c;setPoint(p[1],p[0]);populateSelects();renderCountry();drawAll();}
function renderCountry(){if(!$('countryMetrics'))return;if(!state.ready)return;const f=feature(state.selected),m=metrics(f);$('selectedTitle').textContent=name(f);const cells=[[tr('Сферадағы модельдік аудан','Модельная площадь на сфере'),fmt(m.A/1e6,3),tr('млн км² · шекара бойынша','млн км² · по границам')],[tr('Меркатордағы аудан','Площадь изображения Меркатора'),m.Am===null?'∞':fmt(m.Am/1e6,3),tr('млн км² · экваторға нормаланған','млн км² · нормировано на экватор')],[tr('Орташа аудандық коэффициент','Средний площадной коэффициент'),m.K===null?'∞':fmt(m.K,3)+'×','K̄ = Aₘ / A'],[tr('Ауданның ұлғаюы','Увеличение площади'),m.K===null?'—':'+'+fmt((m.K-1)*100,1)+'%','(K̄ − 1) × 100%']];$('countryMetrics').innerHTML=cells.map(a=>`<div class="metric"><span>${a[0]}</span><b>${a[1]}</b><small>${a[2]}</small></div>`).join('');
 $('countryFoot').textContent=tr('Ендік аралығы: ','Диапазон широт: ')+fmt(m.bounds[0][1],2)+'° … '+fmt(m.bounds[1][1],2)+'°. '+tr('Natural Earth 1:110 млн. Бұл ресми анықтамалық аудан емес.','Natural Earth 1:110 млн. Это не официальная справочная площадь.');
 const midK=M.local(Math.max(-89,Math.min(89,m.center[1]))).K;
 $('countrySteps').innerHTML=m.K===null?tr('Аумақ полюсті қамтиды. Толық Меркатор бейнесінің ауданы шексіз. Экрандағы кесілген бейне толық аумақтың ауданы ретінде есептелмейді.','Территория включает полюс. Полная площадь изображения Меркатора бесконечна; обрезанное изображение не выдаётся за площадь всей территории.'):`<p>${tr('1. Деректер: Natural Earth 4.1.0, world-atlas 2.0.2; сфера радиусы','1. Данные: Natural Earth 4.1.0, world-atlas 2.0.2; радиус сферы')} R = ${fmt(M.R,4)} km.</p><div class="formula">2. A = R² Ω = ${fmt(m.A,1)} km²<br>3. Aₘ = ∬ᴰ sec²φ dA = ${fmt(m.Am,1)} km²<br>4. K̄ = ${fmt(m.Am,1)} / ${fmt(m.A,1)} = ${fmt(m.K,5)}<br>5. Eₐ = (K̄ − 1) × 100% = ${fmt((m.K-1)*100,3)}%</div><p>${tr('Екі ұсақтау дәлдігі арасындағы өзгеріс','Изменение при двух допусках адаптивного разбиения')}: ${fmt(m.numericChange,6)}%. ${tr('Бұл тек сандық тұрақтылық; шекара қатесінің бағасы емес.','Это численная устойчивость, а не оценка погрешности границ.')}</p><p>${tr('Салыстыру үшін сфералық центр ендігі','Для сравнения, широта сферического центроида')} φ = ${fmt(m.center[1],3)}° → K = ${fmt(midK,4)}. ${tr('Интегралдық K̄-дан ауытқу','Отклонение от интегрального K̄')}: ${fmt((midK/m.K-1)*100,2)}%. ${tr('Бұл орталық ендік әдісінің жуықтау екенін көрсетеді.','Это показывает приближённость метода центральной широты.')}</p><p>${tr('Координаталық аудан экранның үлкейтуіне тәуелді емес. Географиялық түсінік: жоғары ендіктегі әрбір шағын бөлік орташа коэффициентке көбірек үлес қосады.','Координатная площадь не зависит от экранного увеличения. Географический смысл: малые части на высоких широтах увеличиваются сильнее, что учитывается при суммировании.')}</p>`;renderComparison();}
function renderComparison(){if(!$('comparison'))return;if(!state.ready)return;const fs=[feature(state.selected),feature(state.compare)],ms=fs.map(metrics),max=Math.max(...ms.flatMap(m=>[m.A,m.Am||0]));$('comparison').innerHTML=fs.map((f,i)=>`<div class="compare-row"><strong>${esc(name(f))}</strong><div>${[[ms[i].A,false],[ms[i].Am,true]].map(([a,o])=>`<div class="bar-line"><div class="bar-track"><div class="bar ${o?'orange-bar':''}" style="width:${a?100*a/max:0}%"></div></div><span>${a?fmt(a/1e6,2)+' '+tr('млн км²','млн км²'):'∞'} ${o?'M':'S'}</span></div>`).join('')}</div></div>`).join('')+`<p class="muted"><span class="cyan-text">S — ${tr('сфера','сфера')}</span> · <span class="orange-text">M — Mercator</span>. ${tr('Сферадағы аудандар қатынасы','Отношение площадей на сфере')}: ${fmt(ms[0].A/ms[1].A,3)}. ${tr('Картада','На карте')}: ${ms[0].Am&&ms[1].Am?fmt(ms[0].Am/ms[1].Am,3):'—'}.</p>`;}
function setPoint(lat,lon){state.lat=Math.max(-89.999,Math.min(89.999,lat));state.lon=M.wrap(lon);$('latitude').value=state.lat.toFixed(4);$('longitude').value=state.lon.toFixed(4);$('latSlider').value=state.lat;renderPoint();drawAll();}
function renderPoint(){if(!$('pointMetrics'))return;let m;try{m=M.local(state.lat,state.lon);$('pointError').textContent='';}catch(e){$('pointError').textContent=tr('Ендік −90° пен 90° арасында, бойлық −180° пен 180° арасында болуы керек.','Широта должна быть строго между −90° и 90°, долгота — между −180° и 180°.');return;}
 $('pointMetrics').innerHTML=[[tr('Сызықтық коэффициент','Линейный коэффициент'),fmt(m.k,3)+'×'],[tr('Аудандық коэффициент','Площадной коэффициент'),fmt(m.K,3)+'×'],[tr('Ауданның ұлғаюы','Рост площади'),'+'+fmt(m.areaPercent,1)+'%']].map(r=>`<div><span>${r[0]}</span><b>${r[1]}</b></div>`).join('');
 $('pointSteps').innerHTML=`<div class="formula">φ = ${fmt(m.lat,4)}° = ${fmt(m.lat*M.RAD,6)} rad<br>cos φ = ${fmt(Math.cos(m.lat*M.RAD),6)}<br>k = 1 / ${fmt(Math.cos(m.lat*M.RAD),6)} = ${fmt(m.k,6)}<br>K = k² = ${fmt(m.K,6)}<br>Eₗ = (k − 1) × 100% = ${fmt(m.linearPercent,2)}%<br>Eₐ = (K − 1) × 100% = ${fmt(m.areaPercent,2)}%</div><p>x = ${fmt(m.x,2)} km · y = ${fmt(m.y,2)} km</p><p>${tr('Бұл — нүкте маңындағы өте шағын ұзындықтар мен аудандарға арналған коэффициенттер. Үлкен аумаққа бір нүктенің мәнін қолдануға болмайды. Масштаб бойлыққа тәуелді емес.','Это коэффициенты для очень малых длин и площадей около точки. Одно значение не описывает всю большую территорию. Масштаб не зависит от долготы.')}</p>`;renderChart();}
function renderChart(){const w=540,h=260,L=42,T=12,B=222,R=520,x=v=>L+(R-L)*v/85,y=v=>B-(B-T)*Math.log10(v)/Math.log10(150);const line=key=>Array.from({length:171},(_,i)=>{const v=i/2;return `${i?'L':'M'}${x(v).toFixed(2)},${y(M.local(v)[key]).toFixed(2)}`}).join(' ');let s=`<svg id="scaleGraph" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Mercator scale factors by latitude"><rect width="540" height="260" fill="#0d1e2e"/>`;
 for(const v of [1,2,4,10,25,100])s+=`<line x1="${L}" y1="${y(v)}" x2="${R}" y2="${y(v)}" stroke="#244055"/><text x="32" y="${y(v)+4}" fill="#93aabd" text-anchor="end" font-size="10">${v}×</text>`;
 for(const v of [0,15,30,45,60,75,85])s+=`<text x="${x(v)}" y="242" fill="#93aabd" text-anchor="middle" font-size="10">${v}°</text>`;
 s+=`<path d="${line('k')}" fill="none" stroke="#6cddd5" stroke-width="2.5"/><path d="${line('K')}" fill="none" stroke="#ffaf73" stroke-width="2.5"/>`;
 if(Math.abs(state.lat)<=85){const a=Math.abs(state.lat);s+=`<line x1="${x(a)}" y1="12" x2="${x(a)}" y2="222" stroke="#dce6ee" stroke-dasharray="3 4" opacity=".5"/>`;for(const [key,col]of [['k','#6cddd5'],['K','#ffaf73']])s+=`<circle cx="${x(a)}" cy="${y(M.local(a)[key])}" r="4" fill="${col}"/>`;}
 s+='</svg>'; $('chart').innerHTML=s;const old=$('exportGraph');if(!old){const b=document.createElement('button');b.id='exportGraph';b.className='quiet';$('chart').parentElement.appendChild(b);b.onclick=()=>download('mercator-scale.svg',new XMLSerializer().serializeToString($('scaleGraph')),'image/svg+xml');}$('exportGraph').textContent=tr('↓ График SVG','↓ График SVG');}
function renderExperiment(){if(!$('expLat'))return;const lat=+$('expLat').value,A=+$('cellArea').value,a=M.strip(0,A),b=M.strip(lat,A);$('expLatLabel').textContent=fmt(lat,1)+'°';const dims=s=>[M.R*s.lonWidth*M.RAD,M.R*(Math.asinh(Math.tan(s.high*M.RAD))-Math.asinh(Math.tan(s.low*M.RAD)))];const ds=[dims(a),dims(b)],scale=Math.min(150/Math.max(...ds.map(x=>x[0])),145/Math.max(...ds.map(x=>x[1])));$('cellVisual').innerHTML=`<svg class="cellsvg" viewBox="0 0 500 220" role="img" aria-label="Equal real area cells in Mercator"><line x1="20" x2="480" y1="180" y2="180" stroke="#244055"/>${ds.map((d,i)=>`<rect x="${(i?365:135)-d[0]*scale/2}" y="${180-d[1]*scale}" width="${d[0]*scale}" height="${d[1]*scale}" fill="${i?'#ffaf7328':'#6cddd528'}" stroke="${i?'#ffaf73':'#6cddd5'}" stroke-width="2"/><text x="${i?365:135}" y="203" text-anchor="middle" fill="#93aabd" font-size="12">${i?fmt(lat,1):0}° · ${fmt(A,0)} km²</text>`).join('')}</svg>`;
 $('cellResults').innerHTML=row(tr('Сферадағы әр аудан','Каждая площадь на сфере'),fmt(A,0)+' km²')+row(tr('Экватор ұяшығының Меркатор ауданы','Меркатор-площадь экваториальной ячейки'),fmt(a.projected,3)+' km²')+row(tr('Таңдалған ұяшықтың Меркатор ауданы','Меркатор-площадь выбранной ячейки'),fmt(b.projected,3)+' km²',true)+row(tr('Шекті ұяшықтың орташа K̄','Среднее K̄ конечной ячейки'),fmt(b.K,6)+'×')+row(tr('Орталық нүктедегі K','K в центральной точке'),fmt(b.localK,6)+'×')+row(tr('Жергілікті жуықтау қатесі','Ошибка локального приближения'),fmt(b.errorPercent,6)+'%')+`<p class="muted">${tr('Теріс таңба жергілікті жуықтаудың нақты ұяшық есебінен кіші екенін білдіреді. Ұяшық өлшемін арттырып, айырманы бақылаңыз.','Отрицательный знак означает, что местное приближение занижает результат для конечной ячейки. Увеличьте размер участка и наблюдайте разницу.')}</p>`;
 $('cellSteps').innerHTML=`<div class="formula">δ = √A / (2R)<br>φ₁ = φ − δ = ${fmt(b.low,6)}°<br>φ₂ = φ + δ = ${fmt(b.high,6)}°<br>Δλ = A / [R²(sinφ₂ − sinφ₁)] = ${fmt(b.lonWidth,6)}°<br>Aₘ = R²Δλ [asinh(tanφ₂) − asinh(tanφ₁)]</div><p>${tr('Барлық тригонометриялық есептеулер радианмен жүргізіледі. Бұл параллельдер мен меридиандар шектеген ұяшық үшін аналитикалық формула; ел шекараларының геодезиялық көпбұрышынан бөлек модель. Экватор ұяшығының орташа K̄-сы 1-ден өте аз үлкен, себебі оның шекарасы нөлдік ендікпен шектелмейді.','Все тригонометрические вычисления выполняются в радианах. Это аналитическая формула для ячейки между параллелями и меридианами; её рёбра отличаются от геодезических рёбер полигона страны. Среднее K̄ экваториальной ячейки чуть больше 1: она имеет ненулевую протяжённость по широте.')}</p>`;}
function renderPhysical(){if(!$('physLat'))return;const p=+$('physLat').value,g=+$('physGlobe').value,m=+$('physMap').value;if(!Number.isFinite(p)||Math.abs(p)>=90||!(g>0)||!(m>0)){$('physicalResults').textContent=tr('Оң ұзындықтар мен жарамды ендікті енгізіңіз.','Введите положительные длины и допустимую широту.');return;}const theory=M.local(p).k,observed=m/g;$('physicalResults').innerHTML=row(tr('Теориялық k','Теоретическое k'),fmt(theory,4))+row(tr('Тәжірибелік k = карта / глобус','Измеренное k = карта / глобус'),fmt(observed,4))+row(tr('Тәжірибелік сызықтық бұрмалану','Измеренное линейное искажение'),fmt((observed-1)*100,2)+'%')+row(tr('Теориядан салыстырмалы ауытқу','Относительное отклонение от теории'),fmt((observed/theory-1)*100,3)+'%');}
let morphFrame=0,morphPlaying=false;
function canvasSetup(id){const c=$(id),r=c.getBoundingClientRect(),w=r.width||500,h=r.height||300,dpr=Math.min(window.devicePixelRatio||1,2);if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);}const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);return {c,ctx,w,h};}
function renderMorph(){if(!$('morph'))return;const{ctx,w,h}=canvasSetup('morph'),t=+$('morphRange').value,s=Math.min(w/7.2,h/5.6);const transform=(lon,lat)=>{const a=lon*M.RAD,b=lat*M.RAD,u=[Math.cos(b)*Math.sin(a),Math.sin(b),Math.cos(b)*Math.cos(a)],v=[a,Math.asinh(Math.tan(b)),0];const X=(1-t)*u[0]+t*v[0],Y=(1-t)*u[1]+t*v[1],Z=(1-t)*u[2];return [w/2+s*(X+.24*Z),h/2-s*(Y+.12*Z),u[2]];};
 for(let lat=-80;lat<=80;lat+=20){ctx.beginPath();for(let lon=-180;lon<=180;lon+=3){const p=transform(lon,lat);lon===-180?ctx.moveTo(p[0],p[1]):ctx.lineTo(p[0],p[1]);}ctx.strokeStyle=lat===0?'#ffaf73':'#6cddd576';ctx.lineWidth=lat===0?1.7:.8;ctx.stroke();}
 for(let lon=-180;lon<=180;lon+=30){ctx.beginPath();for(let lat=-80;lat<=80;lat+=2){const p=transform(lon,lat);lat===-80?ctx.moveTo(p[0],p[1]):ctx.lineTo(p[0],p[1]);}ctx.strokeStyle='#6cddd576';ctx.lineWidth=.8;ctx.stroke();}ctx.fillStyle='#93aabd';ctx.font='11px sans-serif';ctx.fillText('t = '+t.toFixed(2),12,18);}
function animateMorph(time){if(!morphPlaying)return;if(!morphFrame)morphFrame=time;const t=Math.min(1,(time-morphFrame)/4000);$('morphRange').value=t;renderMorph();if(t<1)requestAnimationFrame(animateMorph);else{morphPlaying=false;morphFrame=0;$('play').textContent=tr('▶ Анимация','▶ Анимация');}}
function download(filename,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const viewState={};
function gridLine(lat){return {type:'LineString',coordinates:Array.from({length:181},(_,i)=>[-180+2*i,lat])};}
function drawMap(kind){if(!$(kind)||!state.ready)return;const{ctx,w,h}=canvasSetup(kind),globe=kind==='globe',padding=24;
 const base=globe?Math.min(w*.42,h*.43):Math.min((w-2*padding)/(2*Math.PI),(h-45)/(2*Math.PI));
 const p=globe?d3.geoOrthographic().rotate(state.rotation).translate([w/2,h/2-4]).scale(base*state.globeZoom).clipAngle(90):state.projection==='mercator'?d3.geoMercator().translate([w/2+state.pan[0],h/2-5+state.pan[1]]).scale(base*state.mapZoom):d3.geoEqualEarth().translate([w/2+state.pan[0],h/2-5+state.pan[1]]).scale(Math.min(w/5.7,h/3.1)*state.mapZoom);
 p.precision(.25);const path=d3.geoPath(p,ctx);viewState[kind]={p,w,h,base};
 ctx.save();if(globe){const r=p.scale(),g=ctx.createRadialGradient(w/2-r*.4,h/2-r*.45,0,w/2,h/2,r*1.4);g.addColorStop(0,'#193d52');g.addColorStop(.6,'#102b3d');g.addColorStop(1,'#081621');ctx.beginPath();ctx.arc(w/2,h/2-4,r,0,2*Math.PI);ctx.fillStyle=g;ctx.fill();ctx.strokeStyle='#477789';ctx.lineWidth=1;ctx.stroke();ctx.clip();}else{ctx.beginPath();path({type:'Sphere'});ctx.fillStyle='#0a1a28';ctx.fill();ctx.strokeStyle='#315065';ctx.lineWidth=1;ctx.stroke();ctx.clip();}
 if(!globe&&$('heat').checked&&state.projection==='mercator'){
 for(let lat=-85;lat<85;lat+=.5){const a=p([-180,lat]),b=p([180,Math.min(85.0511,lat+.5)]),K=M.local(lat+.25).K;ctx.fillStyle=d3.interpolateRgbBasis(['#235b64','#3f9188','#d1ba66','#dd7852','#922f51'])(Math.min(1,Math.log(K)/Math.log(30)));ctx.globalAlpha=.5;ctx.fillRect(a[0],b[1],b[0]-a[0],a[1]-b[1]+.5);}ctx.globalAlpha=1;}
 for(const f of state.features){if(f.id==='AFR')continue;const selected=state.selected==='AFR'?isAfrica(f):f.id===state.selected;ctx.beginPath();path(f);ctx.fillStyle=selected?'#e6a46b':(!globe&&$('heat').checked&&state.projection==='mercator'?'#94aab51a':'#304e61');ctx.fill();ctx.strokeStyle=selected?'#ffca96':'#7892a253';ctx.lineWidth=selected?1.2:.55;ctx.stroke();}
 if($('grid').checked){ctx.beginPath();path(d3.geoGraticule().step([30,30])());ctx.strokeStyle='#7c9dad3b';ctx.lineWidth=.6;ctx.stroke();ctx.beginPath();path(gridLine(0));ctx.strokeStyle='#6cddd58a';ctx.lineWidth=1;ctx.stroke();}
 if($('tissot').checked&&!globe){
 // Differential image of a unit tangent circle, scaled for visibility. Derivatives at fixed geographic point.
 const e=1e-4,sz=1.4*M.RAD;
 for(let lat=-60;lat<=60;lat+=30)for(let lon=-150;lon<=150;lon+=30){const a=p([lon,lat]),east=p([lon+e/Math.cos(lat*M.RAD),lat]),north=p([lon,lat+e]);const u=[(east[0]-a[0])/(e*M.RAD)*sz,(east[1]-a[1])/(e*M.RAD)*sz],v=[(north[0]-a[0])/(e*M.RAD)*sz,(north[1]-a[1])/(e*M.RAD)*sz];ctx.beginPath();for(let i=0;i<=40;i++){const q=i/40*2*Math.PI,x=a[0]+u[0]*Math.cos(q)+v[0]*Math.sin(q),y=a[1]+u[1]*Math.cos(q)+v[1]*Math.sin(q);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.fillStyle='#f2c78f25';ctx.fill();ctx.strokeStyle='#f5c98eaa';ctx.lineWidth=.8;ctx.stroke();}
 }
 const point=[state.lon,state.lat],pos=p(point),visible=globe?d3.geoDistance(point,p.invert([w/2,h/2-4]))<Math.PI/2:state.projection!=='mercator'||Math.abs(state.lat)<=M.LIMIT;
 if(visible&&pos.every(Number.isFinite)){ctx.beginPath();ctx.arc(pos[0],pos[1],8,0,2*Math.PI);ctx.fillStyle='#6cddd526';ctx.fill();ctx.beginPath();ctx.arc(pos[0],pos[1],3.5,0,2*Math.PI);ctx.fillStyle='#8effeb';ctx.fill();ctx.strokeStyle='#071321';ctx.lineWidth=1.5;ctx.stroke();}
 ctx.restore();if(!globe){ctx.font='10px sans-serif';ctx.fillStyle='#93aabd';ctx.fillText(state.projection==='mercator'?'x = Rλ   y = R ln tan(π/4 + φ/2)':'Equal Earth · equal-area',16,22);}else{ctx.fillStyle='#6cddd5';ctx.font='10px sans-serif';ctx.fillText('R = 6 371,0088 km',16,22);}
}
function drawAll(){if(state.ready){drawMap('globe');drawMap('map');}}
function getGeo(kind,event){const v=viewState[kind];if(!v)return null;const rect=$(kind).getBoundingClientRect(),x=event.clientX-rect.left,y=event.clientY-rect.top;if(kind==='globe'&&Math.hypot(x-v.w/2,y-(v.h/2-4))>v.p.scale())return null;const q=v.p.invert([x,y]);if(!q||!q.every(Number.isFinite)||Math.abs(q[1])>90||Math.abs(q[0])>180)return null;if(kind==='map'&&state.projection==='mercator'&&Math.abs(q[1])>M.LIMIT)return null;const forward=v.p(q);if(Math.hypot(forward[0]-x,forward[1]-y)>2)return null;return q;}
function bindView(kind){const c=$(kind);let down=null,moved=false;c.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,rot:state.rotation.slice(),pan:state.pan.slice(),id:e.pointerId};moved=false;c.setPointerCapture(e.pointerId);});c.addEventListener('pointermove',e=>{if(down){const dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.hypot(dx,dy)>4)moved=true;if(moved){if(kind==='globe')state.rotation=[down.rot[0]+dx*.35/state.globeZoom,Math.max(-89.9,Math.min(89.9,down.rot[1]-dy*.35/state.globeZoom)),0];else state.pan=[down.pan[0]+dx,down.pan[1]+dy];drawMap(kind);}return;}const q=getGeo(kind,e);if(q){const f=state.features.find(f=>f.id!=='AFR'&&d3.geoContains(f,q));$('hoverCoords').textContent=(f?name(f)+' · ':'')+'φ '+fmt(q[1],2)+'° · λ '+fmt(q[0],2)+'°';}});c.addEventListener('pointerup',e=>{if(down&&!moved){const q=getGeo(kind,e);if(q){const f=state.features.find(f=>f.id!=='AFR'&&d3.geoContains(f,q));if(f&&!$('pointOnly').checked)selectCountry(f.id,q);else setPoint(q[1],q[0]);}}down=null;});c.addEventListener('pointercancel',()=>{down=null;});c.addEventListener('wheel',e=>{e.preventDefault();zoomView(kind,Math.exp(-e.deltaY*.001));},{passive:false});c.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key))return;e.preventDefault();if(e.key==='+'||e.key==='-')zoomView(kind,e.key==='+'?1.2:1/1.2);else if(kind==='globe'){state.rotation[0]+=(e.key==='ArrowLeft'?-8:e.key==='ArrowRight'?8:0);state.rotation[1]=Math.max(-89,Math.min(89,state.rotation[1]+(e.key==='ArrowUp'?8:e.key==='ArrowDown'?-8:0)));drawMap(kind);}else{state.pan[0]+=(e.key==='ArrowLeft'?-20:e.key==='ArrowRight'?20:0);state.pan[1]+=(e.key==='ArrowUp'?-20:e.key==='ArrowDown'?20:0);drawMap(kind);}});}
function zoomView(kind,factor){if(kind==='globe')state.globeZoom=Math.max(.6,Math.min(5,state.globeZoom*factor));else state.mapZoom=Math.max(.7,Math.min(12,state.mapZoom*factor));drawMap(kind);}
const AFRICA=new Set('012 024 072 108 120 140 148 178 180 204 226 231 232 262 266 270 288 324 384 404 426 430 434 450 454 466 478 504 508 516 562 566 624 646 686 694 706 710 716 728 729 732 748 768 788 800 818 834 854 894'.split(' '));
function isAfrica(f){return AFRICA.has(f.id)||f.properties.name==='Somaliland';}
async function loadScript(url){return new Promise((resolve,reject)=>{const s=document.createElement('script'),timer=setTimeout(()=>{s.remove();reject(new Error('Timeout'));},16000);s.src=url;s.onload=()=>{clearTimeout(timer);resolve();};s.onerror=()=>{clearTimeout(timer);s.remove();reject(new Error('Script load failed'));};document.head.appendChild(s);});}
async function ensureScript(globalName,primary,fallback){if(window[globalName])return;try{await loadScript(primary);}catch(e){await loadScript(fallback);}if(!window[globalName])throw Error(globalName+' unavailable');}
async function fetchJSON(url){const r=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error('Data HTTP '+r.status);return r.json();}
function renderLoadReady(){if(!$('loadStatus'))return;$('loadStatus').className='status ready';$('loadStatus').textContent=tr('Геодеректер дайын · ','Геоданные загружены · ')+(state.features.length-1)+tr(' аумақ · Natural Earth 1:110 млн · есептеу браузерде',' территорий · Natural Earth 1:110 млн · вычисления в браузере');}
function renderLoadError(){if(!$('loadStatus'))return;$('loadStatus').className='status error';$('loadStatus').textContent=tr('Картаны жүктеу мүмкін болмады. Интернет байланысын тексеріңіз. Нүкте калькуляторы мен тәжірибелер жұмыс істейді.','Не удалось загрузить карты. Проверьте подключение к интернету. Калькулятор точки и эксперименты продолжают работать.');const b=document.createElement('button');b.textContent=tr('Қайталау','Повторить');b.onclick=bootstrap;$('loadStatus').appendChild(b);}
async function bootstrap(){state.loadError=false;$('loadStatus').className='status';$('loadStatus').textContent=tr('Географиялық деректер жүктелуде…','Загружаем географические данные…');try{
 await Promise.all([ensureScript('d3','https://cdn.jsdelivr.net/npm/d3@7.9.0/dist/d3.min.js','https://unpkg.com/d3@7.9.0/dist/d3.min.js'),ensureScript('topojson','https://cdn.jsdelivr.net/npm/topojson-client@3.1.0/dist/topojson-client.min.js','https://unpkg.com/topojson-client@3.1.0/dist/topojson-client.min.js')]);
 let world;if(window.MERCATOR_WORLD)world=window.MERCATOR_WORLD;else try{world=await fetchJSON('https://cdn.jsdelivr.net/npm/world-atlas@2.0.2/countries-110m.json');}catch(e){world=await fetchJSON('https://unpkg.com/world-atlas@2.0.2/countries-110m.json');}
 state.features=topojson.feature(world,world.objects.countries).features;state.features.forEach((f,i)=>{f.id=f.id&&String(f.id)!=='-99'?String(f.id).padStart(3,'0'):'region-'+i;});const africas=state.features.filter(isAfrica);state.features.push({type:'Feature',id:'AFR',properties:{name:'Africa'},geometry:{type:'MultiPolygon',coordinates:africas.flatMap(f=>M.polygons(f))}});state.cache.clear();state.ready=true;populateSelects();if($('country'))selectCountry(state.selected,requestedPoint);renderLoadReady();if($('verify'))$('verify').disabled=false;
 }catch(e){state.loadError=true;renderLoadError();console.error('Geographic data unavailable',e);}}
async function verify(){const rows=[],add=(what,ok,value)=>rows.push(`<tr><td>${what}</td><td class="${ok?'test-pass':'test-fail'}">${ok?'PASS':'CHECK'}</td><td>${value}</td></tr>`);$('verify').disabled=true;for(const [p,v]of [[0,1],[45,2],[60,4],[75,8+4*Math.sqrt(3)]]){const k=M.local(p).K;add(`K(${p}°)`,Math.abs(k-v)<1e-10,fmt(k,8));}add('|φ| → 90°',M.local(89.999).K>1e9,fmt(M.local(89.999).K,0));
 if(state.ready){for(const id of ['398','304','AFR','124','643','076','036']){$('tests').innerHTML=tr('Есептелуде: ','Вычисляем: ')+name(feature(id));await new Promise(r=>setTimeout(r,15));const f=feature(id),m=metrics(f),b=M.boundaryAreas(f,.1),b2=M.boundaryAreas(f,.025),sphereError=Math.abs(b2.sphere/m.A-1)*100,planeError=Math.abs(b2.plane/m.Am-1)*100,convergence=Math.abs(b2.K/b.K-1)*100;add(esc(name(f)),sphereError<.05&&planeError<.05&&convergence<.05,`ΔA = ${fmt(sphereError,6)}% · ΔAₘ = ${fmt(planeError,6)}% · ΔK̄ = ${fmt(convergence,6)}%`);}}
 else add(tr('Аумақтар','Территории'),false,tr('Геодеректер жүктелмеген','Геоданные не загружены'));
 $('tests').innerHTML=`<table><thead><tr><th>${tr('Сынақ','Проверка')}</th><th>${tr('Мәртебе','Статус')}</th><th>${tr('Айырма / мән','Разница / значение')}</th></tr></thead><tbody>${rows.join('')}</tbody></table><p class="muted">${tr('Аумақтық тексерудің шегі: 0,05%. Бұл келісім шекаралардың географиялық дәлдігін растамайды. ΔK̄ — қадамды кішірейткендегі өзгеріс.','Допуск проверки территорий: 0,05%. Согласие алгоритмов не подтверждает географическую точность границ. ΔK̄ — изменение при уменьшении шага.')}</p>`;state.tests=$('tests').innerText;$('verify').disabled=false;}
if($('lang'))$('lang').onclick=()=>{state.lang=state.lang==='kk'?'ru':'kk';setLanguage();};if($('country'))$('country').onchange=e=>selectCountry(e.target.value);if($('compareCountry'))$('compareCountry').onchange=e=>{state.compare=e.target.value;renderComparison();};if($('recalc'))$('recalc').onclick=()=>{state.cache.clear();renderCountry();};if($('reset'))$('reset').onclick=()=>{state.rotation=[-68,-25,0];state.globeZoom=1;state.mapZoom=1;state.pan=[0,0];drawAll();};
for(const k of ['globe','map']){if(!$(k))continue;bindView(k);$(k+'Plus').onclick=()=>zoomView(k,1.25);$(k+'Minus').onclick=()=>zoomView(k,.8);}
for(const id of ['grid','heat','tissot'])if($(id))$(id).onchange=()=>{$('legend').hidden=!$('heat').checked||state.projection!=='mercator';drawAll();};if($('projection'))$('projection').onchange=e=>{state.projection=e.target.value;state.mapZoom=1;state.pan=[0,0];$('heat').disabled=state.projection!=='mercator';$('legend').hidden=!$('heat').checked||state.projection!=='mercator';$('mapTitle').textContent=state.projection==='mercator'?tr('Меркатор проекциясы','Проекция Меркатора'):'Equal Earth';drawAll();};
for(const id of ['latitude','longitude'])if($(id))$(id).oninput=()=>{if($('latitude').value.trim()===''||$('longitude').value.trim()==='')return;const lat=+$('latitude').value,lon=+$('longitude').value;try{M.local(lat,lon);state.lat=lat;state.lon=lon;$('latSlider').value=lat;renderPoint();drawAll();}catch(e){$('pointError').textContent=tr('−90° < φ < 90°, −180° ≤ λ ≤ 180° болуы керек.','Необходимо −90° < φ < 90°, −180° ≤ λ ≤ 180°.');}};
if($('latSlider'))$('latSlider').oninput=e=>setPoint(+e.target.value,state.lon);if($('expLat'))$('expLat').oninput=renderExperiment;if($('cellArea'))$('cellArea').onchange=renderExperiment;for(const id of ['physLat','physGlobe','physMap'])if($(id))$(id).oninput=renderPhysical;
if($('morphRange'))$('morphRange').oninput=()=>{morphPlaying=false;morphFrame=0;renderMorph();};if($('play'))$('play').onclick=()=>{morphPlaying=!morphPlaying;morphFrame=0;if(morphPlaying)requestAnimationFrame(animateMorph);};if($('verify'))$('verify').onclick=verify;if($('export'))$('export').onclick=()=>{if(!state.ready)return;const quote=x=>'"'+String(x).replace(/"/g,'""')+'"',lines=[['territory','source','sphere_area_km2','mercator_area_km2','mean_K','area_increase_percent','latitude_min_deg','latitude_max_deg','R_km']];for(const id of new Set([state.selected,state.compare])){const f=feature(id),m=metrics(f);lines.push([name(f),'Natural Earth 4.1.0 / world-atlas 2.0.2 / 110m',m.A,m.Am??'Infinity',m.K??'Infinity',m.K===null?'Infinity':(m.K-1)*100,m.bounds[0][1],m.bounds[1][1],M.R]);}download('mercator-results.csv','\ufeff'+lines.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');};
let resizeFrame;window.addEventListener('resize',()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>{drawAll();renderMorph();});});setLanguage();if(requestedPoint&&$('latitude')){setPoint(requestedPoint[1],requestedPoint[0]);$('pointOnly').checked=true;}if($('loadStatus'))bootstrap();
